<x-storefront.layout :title="($selectedCategory?->seo_title ?? $selectedCategory?->name ?? 'Sản phẩm').' - '.config('app.name')" page="products">
    <section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="{{ route('home') }}">Trang chủ</a><span>/</span><span>Sản phẩm</span></div><span class="eyebrow">Cửa hàng O Út</span><h1>{{ $selectedCategory?->name ?? 'Đặc sản Huế nhà làm' }}</h1><p>{{ $selectedCategory?->description ?? 'Chọn theo món, xem giá và biến thể ngay trên danh sách.' }}</p></div></section>
    <section class="section"><div class="container"><form class="shop-toolbar" method="GET" action="{{ route('products.index') }}"><div class="filter-chips"><a class="filter-chip {{ $selectedCategory ? '' : 'is-active' }}" href="{{ route('products.index', request()->only('sort')) }}">Tất cả</a>@foreach ($categories as $category)<a class="filter-chip {{ $selectedCategory?->is($category) ? 'is-active' : '' }}" href="{{ route('products.index', array_filter(['category' => $category->slug, 'sort' => request('sort')])) }}">{{ $category->name }}</a>@endforeach</div><select class="sort-select" name="sort" aria-label="Sắp xếp sản phẩm" onchange="this.form.submit()"><option value="featured" @selected(request('sort', 'featured') === 'featured')>Nổi bật</option><option value="price-asc" @selected(request('sort') === 'price-asc')>Giá thấp đến cao</option><option value="price-desc" @selected(request('sort') === 'price-desc')>Giá cao đến thấp</option><option value="name" @selected(request('sort') === 'name')>Tên A–Z</option></select></form><p class="results-summary">Hiển thị {{ $products->total() }} sản phẩm nhà làm</p><div class="product-grid product-grid--4">@forelse ($products as $product)<x-storefront.partials.product-card :product="$product" />@empty<div class="empty-state"><span class="empty-state__icon"><x-storefront.ui.icon name="search" /></span><h2>Chưa có sản phẩm phù hợp</h2><p>Thử xem tất cả sản phẩm hoặc chọn danh mục khác.</p><a class="btn btn--primary" href="{{ route('products.index') }}">Xem tất cả sản phẩm</a></div>@endforelse</div><div class="pagination-wrap">{{ $products->links() }}</div></div></section>
</x-storefront.layout>